function installFence(getRuntime){
 if(!(global.SkipiBrokerDemo&&global.SkipiBrokerDemo.active)||getRuntime())throw new Error('Demo app host unavailable');
 var disposed=false,rejected=0;
 function admit(event){
  var m=event.data;if(!m||m.ch!=='skipi-plugin')return;
  var runtime=getRuntime(),active=runtime&&runtime._active&&runtime._active();
  var valid=!disposed&&active&&event.source===active.iframe.contentWindow&&event.origin==='null'&&m.v===1&&m.token===active.token
    &&['ready','mounted','resize','nav.close','error','unmounted'].indexOf(m.type)>=0;
  if(valid&&(m.type==='mounted'||m.type==='resize'))valid=Number.isFinite(m.height)&&m.height>=0&&m.height<=20000;
  if(valid&&m.type==='error')valid=typeof m.message==='string'&&m.message.length<=500;
  if(!valid){rejected++;event.stopImmediatePropagation();}
 }
 // Registration precedes create(): same-target listeners run in registration order.
 global.addEventListener('message',admit,true);
 return Object.freeze({dispose:function(){if(disposed)return;var runtime=getRuntime();if(runtime&&runtime.close)runtime.close();disposed=true;global.removeEventListener('message',admit,true);},rejected:function(){return rejected;}});
}
// Each preview owns a canonical runtime once. Closing cancels pending verification;
