function createPreviewRuntime(factory,config){
 var closed=false,opened=false,pending=[],cancelOpen=null;
 var cfg=Object.assign({},config,{loader:{install:function(slug){
  return new Promise(function(resolve,reject){
   if(closed){reject(new Error('Demo preview cancelled'));return;}
   var job={reject:reject};pending.push(job);
   Promise.resolve().then(function(){return config.loader.install(slug);}).then(function(value){
    pending=pending.filter(function(p){return p!==job;});if(!closed)resolve(value);
   },function(error){pending=pending.filter(function(p){return p!==job;});if(!closed)reject(error);});
  });
 }}});
 var runtime=factory(cfg);
 return Object.freeze({open:function(slug,container){if(closed||opened)throw new Error('Demo preview runtime closed');opened=true;var cancelled=new Promise(function(resolve){cancelOpen=function(){resolve({ok:false,stage:'cancelled',reason:'Demo preview closed'});};});return Promise.race([runtime.open(slug,container),cancelled]);},
  close:function(){if(closed)return;closed=true;if(cancelOpen)cancelOpen();pending.splice(0).forEach(function(p){p.reject(new Error('Demo preview cancelled'));});runtime.close();},
  pushTheme:function(theme){if(!closed)runtime.pushTheme(theme);},_active:function(){return closed?null:runtime._active();}});
}
